css:
@import url("https://fonts.googleapis.com/css2?family=Rubik:wght@400;500;600;700&display=swap");
:root{--navy:#13233F;--navy-2:#1E3358;--grn:#16A34A;--grn-2:#22C55E;--grn-l:#E7F6EC;--text:#1F2A3C;--muted:#6B7688;--line:#E3E8EC;--bg:#F4F6F5;--card:#fff;--amber:#F59E0B;--blue:#3B82F6;--pink:#EC4899;
--font:"Rubik",system-ui,-apple-system,"Segoe UI",sans-serif}
*,*::before,*::after{box-sizing:border-box}
body{margin:0;font-family:var(--font);font-size:15px;line-height:1.5;color:var(--text);background:var(--bg);-webkit-font-smoothing:antialiased}
a{color:inherit}img{display:block;max-width:100%}h1,h2,h3{margin:0;color:var(--navy);font-weight:600}
.skip{position:absolute;left:-999px}.skip:focus{left:12px;top:12px;background:var(--grn);color:#fff;padding:10px;z-index:99}
:focus-visible{outline:3px solid var(--grn-2);outline-offset:2px;border-radius:6px}
.app{display:grid;grid-template-columns:76px 1fr;min-height:100vh}
.rail{background:var(--navy);display:flex;flex-direction:column;align-items:center;padding:18px 0;gap:6px;position:sticky;top:0;height:100vh}
.rail .logo{width:42px;height:42px;border-radius:12px;background:var(--grn-2);display:grid;place-items:center;color:var(--navy);font-weight:700;margin-bottom:18px;text-decoration:none}
.rail ul{list-style:none;padding:0;margin:0;display:flex;flex-direction:column;gap:6px}
.rail a{width:48px;height:48px;border-radius:12px;display:grid;place-items:center;color:#8FA0BD;position:relative}
.rail a:hover{background:var(--navy-2);color:#fff}.rail a.on{background:var(--navy-2);color:var(--grn-2)}
.rail a span{position:absolute;left:-9999px}
.rail svg{width:22px;height:22px}
.rail .me{margin-top:auto}.rail .me img{width:40px;height:40px;border-radius:50%;object-fit:cover;border:2px solid var(--grn-2)}
.main{min-width:0;padding:24px 28px 40px}
.top{display:flex;align-items:center;gap:14px;margin-bottom:22px;flex-wrap:wrap}
.menu-btn{display:none;background:#fff;border:1px solid var(--line);border-radius:10px;padding:8px 10px;cursor:pointer}
.top h1{font-size:26px}.top p{margin:2px 0 0;color:var(--muted)}
.top .r{margin-left:auto;display:flex;gap:10px;align-items:center}
.search{display:flex;gap:8px;align-items:center;background:#fff;border:1px solid var(--line);border-radius:10px;padding:9px 12px;color:var(--muted);width:260px}
.search input{border:0;font:inherit;width:100%;color:var(--text)}.search input:focus{outline:none}
.btn{display:inline-flex;align-items:center;gap:8px;padding:10px 16px;border-radius:10px;font-weight:600;font-size:14px;border:1px solid var(--line);background:#fff;cursor:pointer;font-family:var(--font);color:var(--navy)}
.btn.pri{background:var(--grn);border-color:var(--grn);color:#fff}
.kpis{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:16px}
.card{background:var(--card);border:1px solid var(--line);border-radius:16px;padding:18px}
.kpi small{color:var(--muted);font-weight:500}.kpi .v{font-size:28px;font-weight:700;color:var(--navy);margin:4px 0}
.kpi .d{font-size:13px;font-weight:600;color:var(--grn)}.kpi .d.bad{color:#DC2626}
.board-h{display:flex;justify-content:space-between;align-items:center;margin:4px 0 12px;gap:10px;flex-wrap:wrap}
.board-h h2{font-size:18px}.board-h p{margin:0;color:var(--muted);font-size:14px}
.board{display:grid;grid-template-columns:repeat(4,minmax(220px,1fr));gap:14px;overflow-x:auto;padding-bottom:6px;margin-bottom:16px}
.col{background:#EAEEEC;border-radius:16px;padding:12px;min-height:320px;transition:background .15s}
.col.over{background:var(--grn-l);outline:2px dashed var(--grn-2)}
.col-h{display:flex;justify-content:space-between;align-items:center;margin:2px 4px 10px;font-weight:600}
.col-h span{font-size:13px;color:var(--muted);font-weight:500}
.col-h i{display:inline-block;width:10px;height:10px;border-radius:50%;margin-right:8px}
.deal{background:#fff;border:1px solid var(--line);border-radius:12px;padding:12px;margin-bottom:10px;cursor:grab}
.deal:active{cursor:grabbing}.deal.dragging{opacity:.5}
.deal b{display:block;color:var(--navy);font-weight:600}
.deal .co{font-size:13px;color:var(--muted)}
.deal .ft{display:flex;justify-content:space-between;align-items:center;margin-top:10px}
.deal .amt{font-weight:700;color:var(--navy)}
.deal img{width:26px;height:26px;border-radius:50%;object-fit:cover}
.tag{font-size:11px;font-weight:600;border-radius:999px;padding:2px 8px;background:var(--bg);color:var(--muted)}
.tag.hot{background:#FDECEC;color:#DC2626}
.grid3{display:grid;grid-template-columns:1fr 1.2fr 1fr;gap:16px}
.card h2{font-size:17px;margin-bottom:14px}
.gauge{text-align:center}.gauge svg{width:100%;max-width:240px;height:auto;margin:0 auto}
.gauge p{margin:6px 0 0;color:var(--muted);font-size:14px}.gauge b{color:var(--navy)}
.lead-row{display:flex;align-items:center;gap:12px;padding:9px 0;border-bottom:1px solid var(--line)}.lead-row:last-child{border:0}
.lead-row .n{width:22px;font-weight:700;color:var(--muted)}
.lead-row img{width:36px;height:36px;border-radius:50%;object-fit:cover}
.lead-row div{flex:1}.lead-row b{display:block;font-size:14px;color:var(--navy)}
.lead-row .bar{height:6px;background:var(--bg);border-radius:4px;margin-top:4px;overflow:hidden}.lead-row .bar i{display:block;height:100%;background:var(--grn-2)}
.lead-row strong{font-size:14px}
.feed{list-style:none;padding:0;margin:0}
.feed li{display:flex;gap:12px;padding:9px 0;border-bottom:1px solid var(--line);font-size:14px}.feed li:last-child{border:0}
.feed .ic{width:32px;height:32px;border-radius:10px;display:grid;place-items:center;flex:none;font-size:15px}
.feed small{display:block;color:var(--muted)}
.tasks label{display:flex;gap:10px;align-items:flex-start;padding:8px 0;border-bottom:1px solid var(--line);font-size:14px;cursor:pointer}
.tasks input{margin-top:3px;accent-color:var(--grn);width:16px;height:16px}
.tasks input:checked+span{text-decoration:line-through;color:var(--muted)}
.tasks small{display:block;color:var(--muted)}
.foot{color:var(--muted);font-size:13px;margin-top:24px;text-align:center}.foot a{color:var(--grn)}
@media (max-width:1150px){.kpis{grid-template-columns:1fr 1fr}.grid3{grid-template-columns:1fr 1fr}.grid3 > :first-child{grid-column:span 2}}
@media (max-width:760px){.app{grid-template-columns:1fr}.rail{position:fixed;left:0;top:0;z-index:30;width:76px;transform:translateX(-100%);transition:transform .25s}.rail.open{transform:none}.menu-btn{display:block}
.search{display:none}.main{padding:18px 14px 30px}.grid3{grid-template-columns:1fr}.grid3 > :first-child{grid-column:auto}}
@media (max-width:480px){.kpis{grid-template-columns:1fr}}

javascript:
const stages=[["New lead","#3B82F6"],["Contacted","#F59E0B"],["Proposal sent","#EC4899"],["Negotiation","#22C55E"]];
const P=["1494790108377-be9c29b29330","1507003211169-0a1dd7228f2d","1438761681033-6461ffad8d80","1500648767791-00dcc994a43e"];
const deals=[["Website redesign","Harbor Dental",18500,0,0,""],["Annual licence","Parcelio",42000,0,1,"hot"],["Onboarding package","Greenleaf Co",7200,1,2,""],["Team plan upgrade","Lumen Studio",12400,1,3,""],["Enterprise rollout","Kestrel Build",96000,2,0,"hot"],["Support contract","Marlowe Bank",33000,2,1,""],["Renewal + add-ons","Brightwell",54000,3,2,"hot"],["Pilot project","Oakline Retail",15800,3,3,""]];
const board=document.getElementById('board'),f=n=>'$'+n.toLocaleString('en-US');
function draw(){board.innerHTML=stages.map((s,i)=>{const ds=deals.map((d,j)=>[d,j]).filter(x=>x[0][3]===i),t=ds.reduce((a,x)=>a+x[0][2],0);
 return `<div class="col" data-s="${i}" aria-label="${s[0]}"><div class="col-h"><span style="color:#13233F;font-weight:600;font-size:15px"><i style="background:${s[1]}"></i>${s[0]}</span><span>${ds.length} · ${f(t)}</span></div>${ds.map(([d,j])=>`<article class="deal" draggable="true" data-j="${j}" tabindex="0"><b>${d[0]}</b><span class="co">${d[1]}</span><div class="ft"><span class="amt">${f(d[2])}</span>${d[5]?'<span class="tag hot">Hot</span>':'<span class="tag">Q4</span>'}<img src="https://images.unsplash.com/photo-${P[d[4]]}?w=60&q=60&auto=format&fit=crop" alt="" width="26" height="26"></div></article>`).join('')}</div>`}).join('');
 document.getElementById('pv').textContent=f(deals.reduce((a,d)=>a+d[2],0));
 board.querySelectorAll('.deal').forEach(el=>{el.addEventListener('dragstart',e=>{e.dataTransfer.setData('text/plain',el.dataset.j);el.classList.add('dragging')});el.addEventListener('dragend',()=>el.classList.remove('dragging'));
  el.addEventListener('keydown',e=>{if(e.key==='ArrowRight'||e.key==='ArrowLeft'){const d=deals[el.dataset.j];d[3]=Math.min(3,Math.max(0,d[3]+(e.key==='ArrowRight'?1:-1)));draw();board.querySelector(`[data-j="${el.dataset.j}"]`).focus()}})});
 board.querySelectorAll('.col').forEach(c=>{c.addEventListener('dragover',e=>{e.preventDefault();c.classList.add('over')});c.addEventListener('dragleave',()=>c.classList.remove('over'));
  c.addEventListener('drop',e=>{e.preventDefault();deals[e.dataTransfer.getData('text/plain')][3]=+c.dataset.s;draw()})})}
draw();
(()=>{const b=document.querySelector('.burger'),m=document.getElementById('menu'),y=document.getElementById('yr');
if(b&&m){b.addEventListener('click',()=>{const o=m.classList.toggle('open');b.setAttribute('aria-expanded',o)});
m.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>{m.classList.remove('open');b.setAttribute('aria-expanded',false)}))}
if(y)y.textContent=new Date().getFullYear()})();
